  ],
  "claims": [
    {
      "claim_id": "marker_preservation",
      "necessary": "yes",
      "necessity_reason": "Mapping with CHARBOUND and STRIPCC is within the harness's mapping surface. A finite, valid control-containing UTF-8 input can exercise the changed preservation of a boundary marker, but no old harness map call combines those flags.",
      "before": {
        "requirement": "Preserve a CHARBOUND marker through STRIPCC for a retained grapheme.",
        "applicability": "not_applicable",
        "harness_status": "not_applicable",
        "reason": "The old normalization branch treats the negative boundary sentinel as a control and removes it, so this changed behavior is unavailable before the fix.",
        "source_evidence": [
          {
            "unit_id": "u-82fb367dcb7283a12bb8",
            "start_line": 617,
            "end_line": 649,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-13a1a21f0d6cf664dc1d",
            "start_line": 519,
            "end_line": 527,
            "role": "dependency",
            "dependency_reason": "CHARBOUND creates the negative boundary sentinel passed to normalization."
          }
        ]
      },
      "after": {
        "requirement": "Preserve a CHARBOUND marker through STRIPCC for a retained grapheme.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The changed nonnegative control test preserves the sentinel. The old harness has no map call with both CHARBOUND and STRIPCC; its direct UTF-32 calls do not generate a CHARBOUND marker.",
        "source_evidence": [
          {
            "unit_id": "u-c2ddb5ea0940cb0a5374",
            "start_line": 617,
            "end_line": 651,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-2c801e7bf02db2bd8518",
            "start_line": 142,
            "end_line": 165,
            "role": "dependency",
            "dependency_reason": "The added regression cases demonstrate the combined mapping behavior."
          },
          {
            "unit_id": "u-2cf383f70b7c1b31abe9",
            "start_line": 754,
            "end_line": 766,
            "role": "dependency",
            "dependency_reason": "Reencoding converts a retained boundary sentinel to an output marker when CHARBOUND is set."
          }
        ]
      },
      "same_blocker": "not_applicable",
      "harness_evidence": [
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 45,
          "end_line": 73,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 78,
          "end_line": 97,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The same marker-preservation behavior is absent from the old implementation and supported after the change, while the fixed old harness never requests the required combined mapping.",
      "missing_information": [],
      "change_ids": [
        "g0002"
      ]
    },
    {
      "claim_id": "removed_control_boundary",
      "necessary": "yes",
      "necessity_reason": "For valid input containing a removable control, the changed combined mapping removes the boundary marker belonging to that control. The old harness cannot invoke that combination.",
      "before": {
        "requirement": "Remove the CHARBOUND sentinel immediately before a control removed by STRIPCC.",
        "applicability": "not_applicable",
        "harness_status": "not_applicable",
        "reason": "The old branch strips negative sentinels indiscriminately and has no operation that selectively removes the marker preceding a removed control.",
        "source_evidence": [
          {
            "unit_id": "u-82fb367dcb7283a12bb8",
            "start_line": 617,
            "end_line": 649,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-13a1a21f0d6cf664dc1d",
            "start_line": 519,
            "end_line": 527,
            "role": "dependency",
            "dependency_reason": "CHARBOUND inserts the sentinel whose position matters when a following control is removed."
          }
        ]
      },
      "after": {
        "requirement": "Remove the CHARBOUND sentinel immediately before a control removed by STRIPCC, while retaining markers for surviving graphemes.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The new branch removes the preceding sentinel when it removes a control. None of the old harness's map calls enables CHARBOUND and STRIPCC together.",
        "source_evidence": [
          {
            "unit_id": "u-c2ddb5ea0940cb0a5374",
            "start_line": 641,
            "end_line": 653,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-2c801e7bf02db2bd8518",
            "start_line": 145,
            "end_line": 176,
            "role": "dependency",
            "dependency_reason": "The added cases include removable controls and compare combined mapping with a two-step mapping."
          }
        ]
      },
      "same_blocker": "not_applicable",
      "harness_evidence": [
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 51,
          "end_line": 73,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 84,
          "end_line": 97,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "Selective removal of a control's boundary is a distinct changed consequence. The old harness's fixed flags prevent reaching it after the change.",
      "missing_information": [],
      "change_ids": [
        "g0002"
      ]
    },
    {
      "claim_id": "utf32_compose_out_of_range",
      "necessary": "yes",
      "necessity_reason": "The harness directly fuzzes native-endian UTF-32 normalization. A finite input can place 0x110000 between composable codepoints, but every direct normalization call omits COMPOSE.",
      "before": {
        "requirement": "With COMPOSE enabled, preserve an out-of-range UTF-32 entry and prevent composition across it.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The before implementation explicitly passes an out-of-range entry through and resets composition state. The old harness never enables COMPOSE in its direct UTF-32 calls; UTF-8 mapping cannot supply that out-of-range entry as an equivalent input.",
        "source_evidence": [
          {
            "unit_id": "u-82fb367dcb7283a12bb8",
            "start_line": 650,
            "end_line": 669,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-13a1a21f0d6cf664dc1d",
            "start_line": 445,
            "end_line": 450,
            "role": "dependency",
            "dependency_reason": "The UTF-8 mapping decomposition route rejects an out-of-range codepoint."
          }
        ]
      },
      "after": {
        "requirement": "With COMPOSE enabled, preserve an out-of-range UTF-32 entry and prevent composition across it.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The same composition guard remains, and the fixed old harness still omits COMPOSE from every direct UTF-32 normalization call.",
        "source_evidence": [
          {
            "unit_id": "u-c2ddb5ea0940cb0a5374",
            "start_line": 655,
            "end_line": 674,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-ae6bf80e9b730b2ed570",
            "start_line": 445,
            "end_line": 450,
            "role": "dependency",
            "dependency_reason": "The UTF-8 mapping route still rejects an out-of-range codepoint."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 45,
          "end_line": 75,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The obligation and the concrete missing COMPOSE flag on direct UTF-32 calls are identical on both sides.",
      "missing_information": [],
      "change_ids": [
        "g0002"
      ]
    },
    {
      "claim_id": "map_embedded_nul",
      "necessary": "yes",
      "necessity_reason": "Explicit-length utf8proc_map supports an embedded NUL and subsequent bytes. A finite NUL-terminated fuzz input can contain such bytes, but the harness passes strlen(data) as every explicit map length.",
      "before": {
        "requirement": "Exercise explicit-length mapping of valid UTF-8 bytes after an embedded NUL.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The source contract permits embedded NULs in explicit-length input. The old harness's strlen-derived length stops each explicit map call at the first NUL, and its normalization shortcuts use NULLTERM.",
        "source_evidence": [
          {
            "unit_id": "u-06154649df2f273dfde1",
            "start_line": 734,
            "end_line": 761,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-120d2fc54a2858e36756",
            "start_line": 557,
            "end_line": 570,
            "role": "dependency",
            "dependency_reason": "With an explicit length, decomposition continues through bytes before that length rather than stopping at NUL."
          }
        ]
      },
      "after": {
        "requirement": "Exercise explicit-length mapping of valid UTF-8 bytes after an embedded NUL.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The same explicit-length contract and implementation remain. The old harness still truncates its explicit map length at the first NUL.",
        "source_evidence": [
          {
            "unit_id": "u-481dd25063161c22dc5c",
            "start_line": 734,
            "end_line": 761,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-81f02fdeb66cddcb540c",
            "start_line": 557,
            "end_line": 570,
            "role": "dependency",
            "dependency_reason": "The after decomposition path retains explicit-length processing."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 6,
          "end_line": 18,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-1f26bb9c4ca01b89207f",
          "start_line": 78,
          "end_line": 97,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The same explicit-length mapping capability is required on both sides, and strlen(data) is the same concrete blocker.",
      "missing_information": [],
      "change_ids": [
        "g0002"
      ]
    }
  ],
